// Summarize today's execution
const logs = $input.all();
const metadata = $('Start from Module 7').first().json;

// Count records processed by each module
let jobsScraped = 0;
let jobsFiltered = 0;
let jobsLogged = 0;
let contactsFound = 0;
let outreachGenerated = 0;
let errors = [];

for (const log of logs) {
  const data = log.json;
  const module = data.module || '';
  const status = data.status || '';
  const records = parseInt(data.recordsProcessed || data['Records Processed'] || 0);

  if (module.includes('Module 2') && status === 'Success') jobsScraped += records;
  if (module.includes('Module 3') && status === 'Success') jobsFiltered += records;
  if (module.includes('Module 4') && status === 'Success') jobsLogged += records;
  if (module.includes('Module 6') && status === 'Success') contactsFound += records;
  if (module.includes('Module 7') && status === 'Success') outreachGenerated += records;

  if (status === 'Error') {
    errors.push({
      module: module,
      error: data.errorMessage || data['Error Message']
    });
  }
}

return [{
  json: {
    runId: metadata.runId,
    executionDate: new Date().toISOString().split('T')[0],
    executionTime: new Date().toTimeString().split(' ')[0],
    jobsScraped: jobsScraped,
    jobsFiltered: jobsFiltered,
    jobsLogged: jobsLogged,
    contactsFound: contactsFound,
    outreachGenerated: outreachGenerated,
    totalErrors: errors.length,
    errors: errors,
    status: errors.length > 0 ? 'Completed with Errors' : 'Success'
  }
}];

